#include "cso_reader.h"
#include <algorithm>
#include <cstring>
#include <zlib.h>
namespace ax3d {
static uint32_t u32(const uint8_t*p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);}
CsoReader::~CsoReader(){if(f_)fclose(f_);}
bool CsoReader::open(const std::string&p,std::string&e){if(f_){fclose(f_);f_=nullptr;}f_=fopen(p.c_str(),"rb");if(!f_){e="Ouverture CSO impossible";return false;}fseeko(f_,0,SEEK_END);fileSize_=ftello(f_);rewind(f_);uint8_t h[24];if(fread(h,1,24,f_)!=24||memcmp(h,"CISO",4)){e="En-tête CISO invalide";return false;}uint32_t header=u32(h+4);totalBytes_=u32(h+8);blockSize_=u32(h+16);align_=h[21];if(header<24||!blockSize_||blockSize_>4*1024*1024||!totalBytes_){e="Paramètres CISO invalides";return false;}uint64_t count=(uint64_t(totalBytes_)+blockSize_-1)/blockSize_;if(count>2000000||24+4*(count+1)>fileSize_){e="Index CISO tronqué ou trop grand";return false;}index_.resize(count+1);if(fread(index_.data(),4,index_.size(),f_)!=index_.size()){e="Index CISO illisible";return false;}return true;}
bool CsoReader::block(uint32_t n,std::vector<uint8_t>&out,std::string&e){if(n+1>=index_.size()){e="Bloc CISO hors limites";return false;}uint32_t a=index_[n],b=index_[n+1];uint64_t pos=uint64_t(a&0x7fffffff)<<align_,end=uint64_t(b&0x7fffffff)<<align_;if(pos>=fileSize_||end>fileSize_||end<=pos){e="Offsets CISO invalides";return false;}size_t raw=std::min<uint64_t>(blockSize_,uint64_t(totalBytes_)-uint64_t(n)*blockSize_);std::vector<uint8_t>src(end-pos);if(fseeko(f_,pos,SEEK_SET)||fread(src.data(),1,src.size(),f_)!=src.size()){e="Bloc CISO tronqué";return false;}out.resize(raw);if(a&0x80000000){if(src.size()<raw){e="Bloc brut CISO tronqué";return false;}memcpy(out.data(),src.data(),raw);return true;}uLongf dest=raw;int z=uncompress(out.data(),&dest,src.data(),src.size());if(z!=Z_OK||dest!=raw){e="Décompression zlib CISO impossible";return false;}return true;}
bool CsoReader::read(uint64_t off,void*dst,size_t len,std::string&e){if(off+len>totalBytes_){e="Lecture au-delà de l'image CISO";return false;}auto*d=(uint8_t*)dst;while(len){uint32_t n=off/blockSize_;size_t in=off%blockSize_;std::vector<uint8_t>b;if(!block(n,b,e))return false;size_t take=std::min(len,b.size()-in);memcpy(d,b.data()+in,take);d+=take;off+=take;len-=take;}return true;}
}
